package middleware

import (
	"bytes"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestHeimdallBenchDiscardFlushDoesNotReachTheOriginal(t *testing.T) {
	original := &httptest.ResponseRecorder{HeaderMap: make(http.Header), Body: new(bytes.Buffer)}
	var wrap WrapResponseWriter = &flushWriter{basicWriter{ResponseWriter: original}}
	wrap.Discard()
	wrap.(http.Flusher).Flush()
	if original.Flushed {
		t.Fatalf("Flush on a discarded writer still flushed the original writer")
	}
	if got := wrap.Status(); got != http.StatusOK {
		t.Fatalf("Status after Flush = %d, want %d", got, http.StatusOK)
	}
}

